def verify():
    assert abs(3e8 / 1.55e-6 / 1e12 - 193.5) < 0.1
    na = math.sqrt(1.48 ** 2 - 1.46 ** 2); assert abs(na - 0.2425) < 0.001 and abs(math.degrees(math.asin(1.46 / 1.48)) - 80.6) < 0.1
    assert abs(17 * 50 * 0.1 - 85) < 1e-9 and abs(1.24 / 0.8 - 1.55) < 1e-12 and abs(0.8 * 1.55 / 1.24 - 1.0) < 1e-12
    assert abs(40 * 0.25 + 2 * 0.5 + 4 * 0.1 - 11.4) < 1e-9 and abs((28 - 3 - 1) / 0.25 - 96) < 1e-9
    assert abs((1.55e-6) ** 2 * 1e11 / 3e8 * 1e9 - 0.8008) < 0.001 and abs(10 * math.log10(32) - 15.05) < 0.01 and abs(2500 / 32 - 78.125) < 1e-9


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
